# owner: platform
"""Short text notices telling parents about absences."""

from typing import Iterable, List

from rosterkit.models import Student, Mark
from rosterkit.attendance import days_missed
from datetime import date


def check_marks(
    student: Student, marks: List[Mark]
) -> None:
    """Reject marks that belong to a different student."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} is not "
                f"for {student.student_id!r}"
            )


def absent_days(student: Student, marks: List[Mark]):
    """Absent days, oldest first, after vetting marks."""
    check_marks(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return days


def notice_text(student: Student, days: List[date]) -> str:
    """Write the notice for a vetted list of days."""
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    unit = "day" if count == 1 else "days"
    listed = ", ".join(day.isoformat() for day in days)
    return f"{name} missed {count} {unit}: {listed}."


def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Build a parent notice from absent marks."""
    days = absent_days(student, list(marks))
    return notice_text(student, days)
